    organization_key, institution_key, public_surface, hidden_pressure, before_state,
    after_state, relationship_changes, character_changes, chapter_no, seq, status
) VALUES (
    #{p.runId}, #{p.eventKey}, #{p.eventType}, #{p.title}, #{p.triggerCharacterKey}, #{p.targetCharacterKeys}::jsonb,
    #{p.organizationKey}, #{p.institutionKey}, #{p.publicSurface}, #{p.hiddenPressure}, #{p.beforeState}::jsonb,
    #{p.afterState}::jsonb, #{p.relationshipChanges}::jsonb, #{p.characterChanges}::jsonb, #{p.chapterNo}, #{p.seq}, #{p.status}
) RETURNING id
